CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE TABLE "Exercises" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "Category" text NOT NULL,
        "MuscleGroup" text,
        CONSTRAINT "PK_Exercises" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE TABLE "Favorites" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Username" text NOT NULL,
        "ExerciseId" integer NOT NULL,
        CONSTRAINT "PK_Favorites" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Username" text NOT NULL,
        "PasswordHash" text NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE TABLE "Workouts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Date" timestamp with time zone NOT NULL,
        "WorkoutType" text NOT NULL,
        "UserId" integer NOT NULL,
        CONSTRAINT "PK_Workouts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Workouts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE TABLE "WorkoutSets" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SetNumber" integer NOT NULL,
        "Weight" double precision,
        "Reps" integer,
        "Distance" double precision,
        "Time" double precision,
        "WorkoutId" integer NOT NULL,
        "ExerciseId" integer NOT NULL,
        CONSTRAINT "PK_WorkoutSets" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_WorkoutSets_Exercises_ExerciseId" FOREIGN KEY ("ExerciseId") REFERENCES "Exercises" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_WorkoutSets_Workouts_WorkoutId" FOREIGN KEY ("WorkoutId") REFERENCES "Workouts" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

