DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE INDEX "IX_Workouts_UserId" ON "Workouts" ("UserId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE INDEX "IX_WorkoutSets_ExerciseId" ON "WorkoutSets" ("ExerciseId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    CREATE INDEX "IX_WorkoutSets_WorkoutId" ON "WorkoutSets" ("WorkoutId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Exercises"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Exercises") + 1,
            nextval(pg_get_serial_sequence('"Exercises"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260626215615_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260626215615_InitialCreate', '8.0.11');
    END IF;
END $EF$;
COMMIT;

