DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261028235814_V3UserScopedData') THEN
    ALTER TABLE "Users" ADD "CreatedAt" timestamp with time zone NOT NULL DEFAULT TIMESTAMPTZ '-infinity';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261028235814_V3UserScopedData') THEN
    UPDATE "Users" u
    SET "CreatedAt" = COALESCE((SELECT MIN(w."Date") FROM "Workouts" w WHERE w."UserId" = u."Id"), now());
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261028235814_V3UserScopedData') THEN
    ALTER TABLE "Favorites" ADD "UserId" integer;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261028235814_V3UserScopedData') THEN
    UPDATE "Favorites" f
    SET "UserId" = u."Id"
    FROM "Users" u
    WHERE lower(u."Username") = lower(f."Username");

    DELETE FROM "Favorites"
    WHERE "UserId" IS NULL
       OR "ExerciseId" NOT IN (SELECT "Id" FROM "Exercises");

    DELETE FROM "Favorites" a
    USING "Favorites" b
    WHERE a."UserId" = b."UserId"
      AND a."ExerciseId" = b."ExerciseId"
      AND a."Id" > b."Id";
    END IF;
END $EF$;

